BEGIN TRANSACTION;

-- Compensating migration: three method assignments the previous migration made
-- against the rows' own evidence, and one note that is false on its row.
--
-- The remap declared a rule -- write a value only where the row itself supplies
-- it -- and then broke it in three places by following the DR's section 5
-- mapping table instead of reading the rows. An adversarial review caught it.
-- Data migrations are immutable once committed, so this fixes forward.

-- REF-00881 (was VERIFIED-1). The DR mapped VERIFIED-1 to direct-render on the
-- reasoning that the value had been coined for a direct render. This row's own
-- note says otherwise: "Verified via WebSearch (waterforwomenfund.org
-- case-study result, corroborated by the ADB record and academic mentions)".
-- That is corroboration without obtaining the document -- textbook
-- corroborated-not-retrieved, the same epistemic situation as the 71 rows the
-- same migration demoted. Its VERIFIED standing is therefore also unsupported,
-- so it joins them at UNVERIFIED + OPEN rather than keeping a standing the
-- method contradicts.
UPDATE evidence_sources
   SET verification_status='UNVERIFIED',
       verification_disposition='OPEN',
       verification_method='corroborated-not-retrieved',
       verification_note=COALESCE(verification_note||' ','')||
         '[D-0157 CORRECTION 2026-08-04] The remap assigned method=direct-render from the DR mapping '||
         'table; this row''s own note records WebSearch corroboration, not a document render. Method '||
         'and standing corrected to match the row rather than the table.',
       updated_at='2026-08-04 16:55', updated_by_session='session_2026-08-04-d0157-corrections'
 WHERE ref_id='REF-00881' AND verification_method='direct-render';

-- REF-00911 / REF-00912 (were VERIFIED-WITH-CORRECTION). Both carry
-- verified_by_tool='pubmed-abstract-phase-b' and notes recording verification
-- against PubMed. The row supplies 'tool', not 'direct-render'. Standing is
-- unaffected -- they are verified, and a correction during verification is an
-- event, not a lesser standing.
UPDATE evidence_sources
   SET verification_method='tool',
       verification_note=COALESCE(verification_note||' ','')||
         '[D-0157 CORRECTION 2026-08-04] Method direct-render -> tool: verified_by_tool names '||
         'pubmed-abstract-phase-b, so the row supplies tool. Standing unchanged.',
       updated_at='2026-08-04 16:55', updated_by_session='session_2026-08-04-d0157-corrections'
 WHERE ref_id IN ('REF-00911','REF-00912') AND verification_method='direct-render';

-- REF-00903: the PARTIAL-clearing branch appended a note saying "the
-- outstanding-work meaning is carried by verification_disposition=OPEN", but
-- this row is VERIFIED + CLOSED -- the sentence is false on it. Of the five
-- PARTIAL rows this was the only one already VERIFIED, so the branch's blanket
-- note did not fit it. Recorded plainly instead: whatever PARTIAL was flagging
-- here is now unrecorded, which is a finding rather than a fix.
UPDATE evidence_sources
   SET verification_note=COALESCE(verification_note||' ','')||
         '[D-0157 CORRECTION 2026-08-04] The preceding sentence is false on this row: its '||
         'disposition is CLOSED, not OPEN. This row was VERIFIED when metadata_quality=PARTIAL was '||
         'cleared, so no outstanding-work marker replaced it. What PARTIAL flagged here is not '||
         'recorded anywhere forward; recovering it means re-reading the source.',
       updated_at='2026-08-04 16:55', updated_by_session='session_2026-08-04-d0157-corrections'
 WHERE ref_id='REF-00903';

